```typescript
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, Vector3, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, texture, vec2, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];
  const cleanups = [];
  const materials = [];
  const geometries = [];
  const textures = [];

  // ============================================================================
  // 1. BACKDROP PLANE (7 x 6 units at z=-3, vertical gradient)
  // ============================================================================
  const backdropGeo = new PlaneGeometry(7, 6);
  geometries.push(backdropGeo);

  const backdropMat = new MeshBasicNodeMaterial();

  // TSL gradient: vertical lerp from #0b0b10 (bottom) through #101017 to #16161d (top)
  const uvNode = uv();
  const yNorm = uvNode.y; // ranges 0 to 1 (bottom to top in UV space)

  const col0 = vec3(0.0431, 0.0431, 0.0627); // #0b0b10
  const col1 = vec3(0.0627, 0.0627, 0.0902); // #101017
  const col2 = vec3(0.0862, 0.0862, 0.1137); // #16161d

  const grad1 = mix(col0, col1, smoothstep(0, 0.7, yNorm));
  const gradFinal = mix(grad1, col2, smoothstep(0.7, 1, yNorm));

  backdropMat.colorNode = gradFinal;

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -3;
  backdropMesh.renderOrder = 0;
  group.add(backdropMesh);
  materials.push(backdropMat);

  // ============================================================================
  // 2. TORUS KNOT (brushed metal hero with anisotropy)
  // ============================================================================
  const knottGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  knottGeo.center();
  geometries.push(knottGeo);

  const knotMat = new MeshStandardNodeMaterial();

  // Base color: #14141a (surface)
  knotMat.colorNode = uniform(new Color(0x14141a));

  // Roughness with map multiplied in (async load safe)
  let roughnessNode = uniform(0.55);
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((roughTexture) => {
      roughTexture.anisotropy = 16;
      // Build roughness from map: base 0.55 mixed with map value (center 0.9)
      roughnessNode = mix(
        uniform(0.55),
        texture(roughTexture).r.mul(0.92),
        uniform(0.75)
      );
      knotMat.roughnessNode = roughnessNode;
      knotMat.needsUpdate = true;
      textures.push(roughTexture);
    });
  }
  knotMat.roughnessNode = roughnessNode;

  // PBR properties via TSL nodes for proper anisotropic highlight
  knotMat.metalnessNode = uniform(0.55);
  knotMat.clearcoatNode = uniform(0.22);
  knotMat.clearcoatRoughnessNode = uniform(0.35);
  knotMat.anisotropyNode = uniform(0.9);
  knotMat.anisotropyRotation = Math.PI / 2;

  // Scratch normal map for imperfection (strength 0.15)
  const scratchCanvas = document.createElement('canvas');
  scratchCanvas.width = 256;
  scratchCanvas.height = 256;
  const scratchCtx = scratchCanvas.getContext('2d');
  scratchCtx.fillStyle = '#8080ff';
  scratchCtx.fillRect(0, 0, scratchCanvas.width, scratchCanvas.height);

  // Fine directional scratch streaks (brushed metal effect)
  for (let i = 0; i < 3000; i++) {
    const x = Math.random() * scratchCanvas.width;
    const y = Math.random() * scratchCanvas.height;
    const angle = Math.random() * 0.3 - 0.15; // mostly horizontal for tube direction
    const len = Math.random() * 12 + 3;
    const baseAlpha = Math.random() * 0.25 + 0.1;
    scratchCtx.strokeStyle = `rgba(128, 128, ${130 + Math.random() * 15}, ${baseAlpha})`;
    scratchCtx.lineWidth = Math.random() * 0.5 + 0.15;
    scratchCtx.beginPath();
    scratchCtx.moveTo(x, y);
    scratchCtx.lineTo(x + Math.cos(angle) * len, y + Math.sin(angle) * len);
    scratchCtx.stroke();
  }

  const scratchTexture = ctx.THREE.CanvasTexture ? 
    new ctx.THREE.CanvasTexture(scratchCanvas) : 
    new (ctx.THREE.Texture || ctx.THREE.CanvasTexture)(scratchCanvas);
  scratchTexture.needsUpdate = true;

  knotMat.normalMapNode = texture(scratchTexture);
  knotMat.normalScale = new Vector3(0.15, 0.15, 0.15);
  textures.push(scratchTexture);

  const knotMesh = new Mesh(knottGeo, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  knotMesh.castShadow = true;
  knotMesh.receiveShadow = true;
  group.add(knotMesh);
  materials.push(knotMat);

  // ============================================================================
  // 3. PEDESTAL (complete cylindrical base, no slices)
  // ============================================================================
  const pedGeo = new CylinderGeometry(1.1, 1.1, 0.5, 128, 8, false);
  geometries.push(pedGeo);

  const pedMat = new MeshStandardNodeMaterial();
  pedMat.colorNode = uniform(new Color(0x14141a));
  pedMat.roughnessNode = uniform(0.7);
  pedMat.metalnessNode = uniform(0.35);

  const pedMesh = new Mesh(pedGeo, pedMat);
  pedMesh.position.y = -0.35;
  pedMesh.castShadow = true;
  pedMesh.receiveShadow = true;
  group.add(pedMesh);
  materials.push(pedMat);

  // Chamfered top edge (catching key light)
  const chamferGeo = new CylinderGeometry(1.1, 1.08, 0.03, 128, 4, false);
  geometries.push(chamferGeo);

  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.colorNode = uniform(new Color(0x14141a));
  chamferMat.roughnessNode = uniform(0.5);
  chamferMat.metalnessNode = uniform(0.55);
  chamferMat.emissiveNode = uniform(new Color(0x1a1a22));

  const chamferMesh = new Mesh(chamferGeo, chamferMat);
  chamferMesh.position.y = -0.16;
  chamferMesh.castShadow = true;
  chamferMesh.receiveShadow = true;
  group.add(chamferMesh);
  materials.push(chamferMat);

  // ============================================================================
  // 4. CONTACT SHADOW (radial gradient plane, y=-0.36, visible opacity)
  // ============================================================================
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  geometries.push(shadowGeo);

  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;

  // Create radial gradient shadow (dark center fading to transparent)
  const shadowCanvas = document.createElement('canvas');
  shadowCanvas.width = 256;
  shadowCanvas.height = 256;
  const shadowCtx = shadowCanvas.getContext('2d');

  const radGrad = shadowCtx.createRadialGradient(128, 128, 0, 128, 128, 128);
  radGrad.addColorStop(0, 'rgba(0, 0, 0, 0.65)');
  radGrad.addColorStop(0.35, 'rgba(0, 0, 0, 0.25)');
  radGrad.addColorStop(0.7, 'rgba(0, 0, 0, 0.05)');
  radGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  shadowCtx.fillStyle = radGrad;
  shadowCtx.fillRect(0, 0, shadowCanvas.width, shadowCanvas.height);

  const shadowTexture = ctx.THREE.CanvasTexture ? 
    new ctx.THREE.CanvasTexture(shadowCanvas) : 
    new (ctx.THREE.Texture || ctx.THREE.CanvasTexture)(shadowCanvas);
  shadowTexture.needsUpdate = true;

  shadowMat.map = shadowTexture;
  textures.push(shadowTexture);

  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.36, 0.02);
  shadowMesh.scale.set(1.5, 1.5, 1);
  group.add(shadowMesh);
  materials.push(shadowMat);

  // ============================================================================
  // 5. LIGHTING (key + rim accent at spec red + fill)
  // ============================================================================
  // Key light: 1.2 intensity at 30-45 degree angle
  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.4, 1.8, 1.2);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 2048;
  keyLight.shadow.mapSize.height = 2048;
  keyLight.shadow.camera.near = 0.1;
  keyLight.shadow.camera.far = 10;
  keyLight.shadow.camera.left = -3;
  keyLight.shadow.camera.right = 3;
  keyLight.shadow.camera.top = 3;
  keyLight.shadow.camera.bottom = -3;
  keyLight.shadow.bias = -0.001;
  group.add(keyLight);

  // Rim light: accent red (#ff2a38 signal red) at 0.9 intensity opposite
  const rimLight = new ctx.THREE.DirectionalLight(0xff2a38, 0.9);
  rimLight.position.set(-1.6, 1.4, -1.8);
  group.add(rimLight);

  // Fill light: soft ambient from above-front
  const fillLight = new ctx.THREE.DirectionalLight(0xd4d8e0, 0.35);
  fillLight.position.set(0, 1.2, 0.8);
  group.add(fillLight);

  // ============================================================================
  // 6. TEXT CONTENT
  // ============================================================================
  // Headline: "Material study 03" (68px, 600 weight, centered, paper color)
  const headlineText = ctx.fontAtlas.createText('Material study 03', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0
  });
  headlineText.position.set(0, -1.2, 0.1);
  group.add(headlineText);

  // Caption: "GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT" (18px, 400 weight, mono, uppercase)
  const captionText = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44 // 0.08 * 18
  });
  captionText.position.set(0, -1.6, 0.1);
  group.add(captionText);

  // ============================================================================
  // 7. ORBIT ANIMATION (load trigger, speed 0.1 rad/s, radius 0.4)
  // ============================================================================
  const orbitResult = ctx.primitives['orbit'](group, {
    speed: 0.1,
    radius: 0.4
  });
  if (orbitResult && orbitResult.cleanup) {
    cleanups.push(orbitResult.cleanup);
  }

  // ============================================================================
  // 8. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    // Kill all timelines
    timelines.forEach(tl => tl && tl.kill());

    // Call all cleanup functions
    cleanups.forEach(fn => fn && fn());

    // Dispose materials
    materials.forEach(mat => mat && mat.dispose());

    // Dispose geometries
    geometries.forEach(geo => geo && geo.dispose());

    // Dispose textures
    textures.forEach(tex => tex && tex.dispose());
  };

  group.userData.handlers = {};

  return group;
}
